#!/usr/bin/env node
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const PKG = join(dirname(fileURLToPath(import.meta.url)), '..');

const FILES = {
  FRAUNCES: 'Fraunces-latin.woff2',
  SPACE_GROTESK: 'SpaceGrotesk-latin.woff2',
  JETBRAINS_MONO: 'JetBrainsMono-latin.woff2',
};

const header = `/**
 * GENERATED by scripts/build-fonts.mjs. Do not hand-edit.
 *
 * The three latin woff2 faces, base64 inline. They are EMBEDDED rather than fetched because
 * a render happens inside a sandbox whose egress is dropped before the authored film runs,
 * and because a fetch of any kind can hang rather than fail: an earlier version served them
 * with staticFile() and every sandbox render died on
 * \`A delayRender() "Loading Fraunces" was called but not cleared after 28000ms\`, with egress
 * both up and down. A data: URI makes no request at all, so there is nothing to hang and no
 * asset server to depend on.
 *
 * To change a face, edit scripts/build-fonts.mjs and re-run it.
 */
`;

const parts = [header];
for (const [name, file] of Object.entries(FILES)) {
  const bytes = readFileSync(join(PKG, 'public', 'fonts', file));
  if (bytes.subarray(0, 4).toString('latin1') !== 'wOF2') {
    throw new Error(`${file} is not a woff2 file (magic is not wOF2)`);
  }
  parts.push(`/** ${file} (${bytes.length} bytes) */\nexport const ${name}_WOFF2 =\n  '${bytes.toString('base64')}';\n`);
}
writeFileSync(join(PKG, 'src', 'fonts.data.ts'), parts.join('\n'));
console.log(`fonts.data.ts regenerated from ${Object.keys(FILES).length} faces`);
